record.field:
if record.snapshot_id.futures_notional_value > 0.05 * record.snapshot_id.total_value:
    env['hat_sentry.alert'].create({
        'severity': 'critical',
        'category': 'futures',
        'title': 'Futures exposure exceeds 5%',
        'message': f'Futures notional: {record.snapshot_id.futures_notional_value:.2f} ({record.snapshot_id.futures_notional_value/record.snapshot_id.total_value*100:.1f}%)',
        'recommended_action': 'Reduce futures positions',
        'company_id': record.company_id.id,
    })
